import type { AnimationGroup } from "@babylonjs/lite";

/**
 * Freeze a playing clip at its current moment so hand-set node transforms stick.
 *
 * Pausing alone is not enough: the group's controller still re-applies its
 * pose every tick, even when not playing. Setting `_stopped` makes every
 * driver (scene auto-tick, AnimationManager task, weighted glTF/property mixers)
 * skip the group completely. Unlike stopAnimation(), this keeps `currentTime`
 * instead of resetting it, and unlike goToFrame() it never re-evaluates the pose.
 *
 * @returns `resume`, which plays the clip on from the frozen time at its own
 *          speedRatio and lets it drive the nodes again.
 */
export function freezeForPosing(group: AnimationGroup): () => void {
    const frozenTime = group.currentTime;
    let frozen = true;

    group.isPlaying = false;
    group._stopped = true;

    return () => {
        if (!frozen) {
            return;
        }
        frozen = false;
        group.currentTime = frozenTime;
        group._stopped = false;
        group.isPlaying = true;
    };
}
```

I implemented `freezeForPosing` by setting `_stopped = true` and `isPlaying = false`, because a paused group's controller still rewrites the pose each tick, while `_stopped` makes the scene tick, the manager task and both mixers skip the group. `resume` restores the saved `currentTime` and sets `_stopped = false` and `isPlaying = true`, leaving `speedRatio` untouched.

Not sure of:
- `_stopped` is an `@internal` field, so a library update could change it, though it is in the 1.39.0 declarations you gave me.
- I couldn't see the controller's `tick`, so I'm assuming it writes poses whether or not it is playing, which `goToFrame` suggests.
- A non-looping clip that finished before the freeze will play again on resume rather than staying finished.
